#!/usr/bin/env node
/**
 * Build or refresh the shared project context store (`~/.dsh/context`).
 *
 * One card per project, `projects/<slug>.md`, with front matter (`name`, `path`,
 * `deploy`, `remote`, `updated`) and an auto-generated section between markers.
 * Everything outside the markers (a `## Facts` list that agents append to with
 * `remember`, notes a person wrote) is preserved on every rescan.
 *
 * The point is to settle, once, what every agent otherwise asks: where does this
 * deploy, how is it built, which account, which instructions file.
 *
 * Usage: node tools/context-scan.mjs [--root DIR]... [--out DIR] [--only NAME]
 */

import { execFileSync } from 'node:child_process';
import { existsSync, mkdirSync, readdirSync, readFileSync, realpathSync, statSync, writeFileSync } from 'node:fs';
import { homedir } from 'node:os';
import { basename, join, relative } from 'node:path';

const AUTO_START = '<!-- auto:start (regenerated by context-scan; edit outside these markers) -->';
const AUTO_END = '<!-- auto:end -->';

function args(argv) {
  const out = { roots: [], out: join(homedir(), '.dsh', 'context'), only: undefined };
  for (let i = 0; i < argv.length; i += 1) {
    if (argv[i] === '--root') out.roots.push(argv[++i]);
    else if (argv[i] === '--out') out.out = argv[++i];
    else if (argv[i] === '--only') out.only = argv[++i];
  }
  if (out.roots.length === 0) out.roots.push(join(homedir(), 'Documents', 'Documents', 'Projects'));
  return out;
}

const read = (file, max = 200_000) => {
  try {
    const text = readFileSync(file, 'utf8');
    return text.length > max ? text.slice(0, max) : text;
  } catch {
    return undefined;
  }
};
const json = (file) => {
  const text = read(file);
  if (text === undefined) return undefined;
  try { return JSON.parse(text); } catch { return undefined; }
};
const git = (dir, ...a) => {
  try {
    return execFileSync('git', ['-C', dir, ...a], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'], timeout: 5000 }).trim();
  } catch {
    return '';
  }
};

export function slugify(name) {
  return name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || 'project';
}

/** First meaningful prose line of a README. */
function readmeSummary(dir) {
  for (const name of ['README.md', 'readme.md', 'README']) {
    const text = read(join(dir, name), 20_000);
    if (text === undefined) continue;
    for (const raw of text.split('\n')) {
      const line = raw.trim();
      if (line.length < 20 || /^(#|!\[|\[!|<|```|\||-{3}|>)/.test(line)) continue;
      return line.replace(/\*\*/g, '').slice(0, 240);
    }
  }
  return undefined;
}

/** Loose reads of a wrangler config (toml or json/jsonc). */
function wrangler(dir) {
  const found = [];
  for (const name of ['wrangler.jsonc', 'wrangler.json', 'wrangler.toml']) {
    const text = read(join(dir, name), 50_000);
    if (text === undefined) continue;
    const worker = /["']?name["']?\s*[:=]\s*["']([^"']+)["']/.exec(text)?.[1];
    const domains = [...text.matchAll(/["']?pattern["']?\s*[:=]\s*["']([^"']+)["']/g)].map((m) => m[1]);
    const account = /["']?account_id["']?\s*[:=]\s*["']([^"']+)["']/.exec(text)?.[1];
    const pages = /pages_build_output_dir/.test(text);
    found.push({ file: name, worker, domains, account, pages });
  }
  return found;
}

/** Commands in a deploy doc that look like the deploy itself. */
function deployDocCommands(text) {
  const commands = [];
  for (const block of text.matchAll(/```(?:bash|sh|shell|zsh)?\n([\s\S]*?)```/g)) {
    for (const line of block[1].split('\n')) {
      const value = line.trim();
      if (/deploy|publish|wrangler|caprover|vercel|netlify|fly |sf |spacefast|rsync|scp |docker push|firebase/i.test(value) && !value.startsWith('#')) {
        commands.push(value.replace(/\s+#.*$/, ''));
      }
    }
  }
  return [...new Set(commands)].slice(0, 6);
}

/** Everything the scanner can tell about one project directory. */
export function scanProject(dir) {
  const name = basename(dir);
  const pkg = json(join(dir, 'package.json'));
  const facts = { name, path: dir, stack: [], deploy: [], deployDocs: [], agentDocs: [], scripts: {} };
  facts.description = (typeof pkg?.description === 'string' && pkg.description.length > 0 ? pkg.description : undefined) ?? readmeSummary(dir);

  // Stack
  const deps = { ...(pkg?.dependencies ?? {}), ...(pkg?.devDependencies ?? {}) };
  const stackMap = [['astro', 'Astro'], ['next', 'Next.js'], ['@sveltejs/kit', 'SvelteKit'], ['svelte', 'Svelte'], ['nuxt', 'Nuxt'], ['vue', 'Vue'], ['react', 'React'], ['expo', 'Expo'], ['react-native', 'React Native'], ['electron', 'Electron'], ['hono', 'Hono'], ['wrangler', 'Cloudflare Workers'], ['vite', 'Vite'], ['remotion', 'Remotion'], ['convex', 'Convex'], ['@shopify/shopify-app-remix', 'Shopify app']];
  for (const [dep, label] of stackMap) if (deps[dep] !== undefined && !facts.stack.includes(label)) facts.stack.push(label);
  for (const [file, label] of [['pyproject.toml', 'Python'], ['requirements.txt', 'Python'], ['Cargo.toml', 'Rust'], ['go.mod', 'Go'], ['Package.swift', 'Swift'], ['pubspec.yaml', 'Flutter'], ['composer.json', 'PHP'], ['Gemfile', 'Ruby'], ['pnpm-workspace.yaml', 'pnpm monorepo']]) {
    if (existsSync(join(dir, file)) && !facts.stack.includes(label)) facts.stack.push(label);
  }
  try {
    if (readdirSync(dir).some((n) => n.endsWith('.xcodeproj') || n.endsWith('.xcworkspace'))) facts.stack.push('Xcode');
  } catch { /* ignore */ }
  if (pkg?.packageManager) facts.packageManager = String(pkg.packageManager).split('@')[0];

  // Scripts that matter for agents
  for (const [key, value] of Object.entries(pkg?.scripts ?? {})) {
    if (/^(dev|build|test|check|lint|typecheck|start|preview)$|deploy|publish|release/i.test(key)) facts.scripts[key] = String(value).slice(0, 160);
  }

  // Deploy signals
  for (const w of wrangler(dir)) {
    facts.deploy.push(`Cloudflare ${w.pages ? 'Pages' : 'Worker'}${w.worker ? ` \`${w.worker}\`` : ''} (${w.file})${w.domains.length > 0 ? ` → ${w.domains.slice(0, 4).join(', ')}` : ''}${w.account ? `, account ${w.account}` : ''}`);
  }
  if (existsSync(join(dir, '.spacefast'))) {
    const link = read(join(dir, '.spacefast', 'project.json')) ?? read(join(dir, '.spacefast', 'config.json')) ?? '';
    const space = /"(?:spaceId|space|id|slug)"\s*:\s*"([^"]+)"/.exec(link)?.[1];
    facts.deploy.push(`Spacefast space${space ? ` \`${space}\`` : ''} (.spacefast/)`);
  }
  if (existsSync(join(dir, 'captain-definition'))) facts.deploy.push('CapRover (captain-definition)');
  if (existsSync(join(dir, 'vercel.json')) || existsSync(join(dir, '.vercel', 'project.json'))) facts.deploy.push('Vercel');
  if (existsSync(join(dir, 'netlify.toml'))) facts.deploy.push('Netlify (netlify.toml)');
  if (existsSync(join(dir, 'fly.toml'))) facts.deploy.push('Fly.io (fly.toml)');
  if (existsSync(join(dir, 'firebase.json'))) facts.deploy.push('Firebase (firebase.json)');
  if (existsSync(join(dir, 'app.yaml'))) facts.deploy.push('Google App Engine (app.yaml)');
  if (existsSync(join(dir, 'Dockerfile')) && facts.deploy.length === 0) facts.deploy.push('Docker image (Dockerfile)');
  if (existsSync(join(dir, 'eas.json'))) facts.deploy.push('Expo EAS (eas.json)');
  if (existsSync(join(dir, 'fastlane'))) facts.deploy.push('fastlane');
  if (existsSync(join(dir, 'cordis.patch.yml')) || pkg?.dsh !== undefined) facts.deploy.push('DeepSeek Harness bundle (linked into a dsh profile)');
  try {
    const workflows = readdirSync(join(dir, '.github', 'workflows')).filter((n) => /deploy|publish|release|pages/i.test(n));
    if (workflows.length > 0) facts.deploy.push(`GitHub Actions: ${workflows.slice(0, 4).join(', ')}`);
  } catch { /* none */ }

  // Deploy docs, and the commands in them
  const docCandidates = ['DEPLOY.md', 'DEPLOYMENT.md', 'deploy.md', 'docs/deploy.md', 'docs/DEPLOY.md', 'docs/deployment.md', 'OPERATIONS.md', 'RUNBOOK.md'];
  const seenDocs = new Set();
  for (const rel of docCandidates) {
    const text = read(join(dir, rel), 100_000);
    if (text === undefined) continue;
    // macOS is case-insensitive: DEPLOY.md and deploy.md are one file.
    let real = rel.toLowerCase();
    try { real = realpathSync.native(join(dir, rel)).toLowerCase(); } catch { /* keep */ }
    if (seenDocs.has(real)) continue;
    seenDocs.add(real);
    facts.deployDocs.push({ file: rel, commands: deployDocCommands(text) });
  }
  for (const rel of ['AGENTS.md', 'CLAUDE.md', '.cursorrules', 'GEMINI.md']) if (existsSync(join(dir, rel))) facts.agentDocs.push(rel);

  // Git
  try {
    if (statSync(join(dir, '.git')).isFile()) {
      const common = git(dir, 'rev-parse', '--path-format=absolute', '--git-common-dir').replace(/\/\.git$/, '');
      if (common.length > 0) facts.worktreeOf = common;
    }
  } catch { /* not git */ }
  if (existsSync(join(dir, '.git'))) {
    facts.remote = git(dir, 'remote', 'get-url', 'origin') || undefined;
    facts.branch = git(dir, 'rev-parse', '--abbrev-ref', 'HEAD') || undefined;
    const last = git(dir, 'log', '-1', '--format=%cs %s');
    facts.lastCommit = last.length > 0 ? last.slice(0, 140) : undefined;
  }
  return facts;
}

/** The one-line deploy summary for front matter. */
/** Deploy-ish scripts, best first: `deploy`, deploy*, then release/publish. */
function deployScripts(f) {
  const rank = (k) => (k === 'deploy' ? 0 : /^deploy/i.test(k) ? 1 : /deploy/i.test(k) ? 2 : /^(release|publish)$/i.test(k) ? 3 : 4);
  return Object.keys(f.scripts).filter((k) => /deploy|publish|release/i.test(k)).sort((a, b) => rank(a) - rank(b));
}

function deployLine(f) {
  const scripts = deployScripts(f);
  const pm = f.packageManager ?? 'pnpm';
  const parts = [];
  if (f.deployDocs.length > 0) parts.push(`see ${f.deployDocs[0].file}`);
  if (scripts.length > 0) parts.push(`\`${pm} run ${scripts[0]}\``);
  if (f.deploy.length > 0) parts.push(f.deploy[0].replace(/`/g, ''));
  const line = parts.length > 0 ? parts.join('; ') : 'unknown (no deploy config found)';
  return f.worktreeOf ? `${line} [worktree of ${basename(f.worktreeOf)}]` : line;
}

/** The generated section. */
export function renderAuto(f) {
  const lines = [AUTO_START, `# ${f.name}`, ''];
  if (f.description) lines.push(f.description, '');
  lines.push(`- **Path:** \`${f.path}\``);
  if (f.remote) lines.push(`- **Remote:** ${f.remote}${f.branch ? ` (checked out: \`${f.branch}\`)` : ''}`);
  if (f.worktreeOf) lines.push(`- **Git worktree of:** \`${f.worktreeOf}\` — the deploy config below is that repo's, on branch \`${f.branch ?? '?'}\``);
  if (f.lastCommit) lines.push(`- **Last commit:** ${f.lastCommit}`);
  if (f.stack.length > 0) lines.push(`- **Stack:** ${f.stack.join(', ')}${f.packageManager ? ` · ${f.packageManager}` : ''}`);
  if (f.agentDocs.length > 0) lines.push(`- **Agent instructions:** ${f.agentDocs.join(', ')} (read before working)`);
  lines.push('', '## Deploy');
  if (f.deployDocs.length > 0) {
    for (const doc of f.deployDocs) {
      lines.push(`- **Runbook:** \`${join(f.path, doc.file)}\` — follow it; it is the source of truth.`);
      for (const command of doc.commands) lines.push(`  - \`${command}\``);
    }
  }
  for (const target of f.deploy) lines.push(`- ${target}`);
  const scripts = deployScripts(f);
  for (const key of scripts) lines.push(`- script \`${key}\`: \`${f.scripts[key]}\``);
  if (f.deployDocs.length === 0 && f.deploy.length === 0 && scripts.length === 0) {
    lines.push('- No deploy config found in the repo. If you settle it, record it with `remember`.');
  }
  const other = Object.entries(f.scripts).filter(([k]) => !/deploy|publish|release/i.test(k));
  if (other.length > 0) {
    lines.push('', '## Commands');
    for (const [key, value] of other) lines.push(`- \`${key}\`: \`${value}\``);
  }
  lines.push(AUTO_END);
  return lines.join('\n');
}

/** Merge a fresh scan into an existing card, keeping everything a person or agent added. */
export function mergeCard(existing, f) {
  const front = ['---', `name: ${f.name}`, `path: ${f.path}`, `deploy: ${deployLine(f)}`];
  if (f.remote) front.push(`remote: ${f.remote}`);
  front.push(`updated: ${new Date().toISOString().slice(0, 10)}`, '---');
  const auto = renderAuto(f);
  if (existing === undefined) return `${front.join('\n')}\n${auto}\n\n## Facts\n`;
  let body = existing.replace(/^---\n[\s\S]*?\n---\n?/, '');
  // Keep human-set front matter keys we do not generate (e.g. `deploy` written by a person wins when marked).
  const oldMeta = /^---\n([\s\S]*?)\n---/.exec(existing)?.[1] ?? '';
  const pinned = /^deploy!:\s*(.+)$/m.exec(oldMeta);
  if (pinned !== null) front.splice(3, 1, `deploy!: ${pinned[1]}`, `deploy: ${pinned[1]}`);
  const start = body.indexOf(AUTO_START);
  const end = body.indexOf(AUTO_END);
  body = start >= 0 && end > start ? `${body.slice(0, start)}${auto}${body.slice(end + AUTO_END.length)}` : `${auto}\n\n${body}`;
  if (!/^## Facts\s*$/m.test(body)) body = `${body.trimEnd()}\n\n## Facts\n`;
  return `${front.join('\n')}\n${body.replace(/^\n+/, '')}`;
}

/** Is this directory a project worth a card? */
function isProject(dir) {
  return ['.git', 'package.json', 'pyproject.toml', 'Cargo.toml', 'go.mod', 'Package.swift', 'pubspec.yaml', 'wrangler.toml', 'wrangler.jsonc', 'composer.json'].some((n) => existsSync(join(dir, n)));
}

function main() {
  const options = args(process.argv.slice(2));
  const projectsDir = join(options.out, 'projects');
  mkdirSync(projectsDir, { recursive: true });
  const index = [];
  const seen = new Set();
  for (const root of options.roots) {
    let names = [];
    try { names = readdirSync(root); } catch { continue; }
    for (const name of names) {
      if (name.startsWith('.')) continue;
      const dir = join(root, name);
      try { if (!statSync(dir).isDirectory()) continue; } catch { continue; }
      if (options.only !== undefined && name !== options.only) continue;
      if (!isProject(dir)) continue;
      const facts = scanProject(dir);
      let slug = slugify(name);
      while (seen.has(slug)) slug = `${slug}-2`;
      seen.add(slug);
      const file = join(projectsDir, `${slug}.md`);
      writeFileSync(file, mergeCard(read(file), facts));
      index.push({ slug, name, path: dir, deploy: deployLine(facts), last: facts.lastCommit ?? '' });
    }
  }
  index.sort((a, b) => b.last.localeCompare(a.last));
  const readme = [
    '# Shared project context',
    '',
    'One card per project in `projects/`. Every harness agent and worker reads the card for its working directory;',
    'agents add durable facts with the `remember` tool (or a `FACT:` line in a worker report).',
    'Rescan: `node <dsh-external-agents>/tools/context-scan.mjs`. Text outside the auto markers is never overwritten;',
    'to pin a deploy line by hand, add `deploy!: <text>` to a card\'s front matter.',
    '',
    '| Project | Deploy | Last commit |',
    '| --- | --- | --- |',
    ...index.map((p) => `| [${p.name}](projects/${p.slug}.md) | ${p.deploy.replace(/\|/g, '/')} | ${p.last.slice(0, 60).replace(/\|/g, '/')} |`),
    '',
  ];
  if (options.only === undefined) writeFileSync(join(options.out, 'README.md'), readme.join('\n'));
  process.stdout.write(`${index.length} project card(s) in ${relative(process.cwd(), projectsDir) || projectsDir}\n`);
}

if (import.meta.url === `file://${process.argv[1]}`) main();
